  {
    "id": "c014",
    "name": "Policy Execution and Validity Condition",
    "text": "The Insurer has caused this Policy to be signed and attested by its authorized officers, but it shall not be valid unless also signed by another duly authorized representative of the insurer,"
  },
  {
    "id": "c015",
    "name": "1. Insuring Agreements",
    "text": "In consideration of payment of the premium, and in reliance on ail Statements made in the Application for this Policy and all information provided to the Insurer, and Subject to all the provisions of this Policy, the Insurer designated as such in the Declarations and the Parent Company, on behalf of all Insureds, agree as follows: 1, INSURING AGREEMENTS The Insurer shall pay in connection with a Wrongful Act which takes place before or during the Policy Period all Loss on behaif of the insureds arising from a: A. Claim for a Wrongful Employment Act made against any Insured by or on behaif Employee; or 8. Third Party Claim for a Wrongful Third Party Act made against any Insured, but solely if Third Party Claim Coverage is included in tern 7 in the Declarations; provided that the Claim is first made against the Insureds during the Policy Period or the Extended Reporting Period, if applicable, and reported in writing to the Insurer as soon @S8 practicable atter any insured first becomes aware of such Claim, but in no event later than Sixty (60) days after the expiration of the Policy Period or the Extended Reporting Period, if applicable,"
  },
  {
    "id": "c016",
    "name": "II.A. Spouses — Imputed Loss",
    "text": "A. Spouses if a Claim made against an insured Individual includes a claim against the Insured Individual's lawful spouse solely by reason of (1} such spouse's status as a Spouse of the Insured Individual, or (2} such spouse's ownership interest in property from which the claimant seeks recovery for the Wrongful Acts of the Insured Individual, all loss which such spouse becomes legaily obligated to Pay on account of such claim shall be treated for Purposes of this Policy as Loss which the Insured individual is legally obligated to pay on account of the Ciaim made against the insured Individual,"
  },
  {
    "id": "c017",
    "name": "II.A. Spouses — Extent of Coverage",
    "text": "Such loss shall be covered under this Policy only if and to the extent that such loss would be covered under this Policy if incurred by the Insured Individual."
  },
  {
    "id": "c018",
    "name": "II.A. Spouses — Wrongful Acts Exclusion",
    "text": "The coverage extension afforded by this Subsection does not apply to any Claim alleging any wrongful act or omission by an Insured individual's Spouse."
  },
  {
    "id": "c019",
    "name": "II.A. Spouses — Definition of Spouse",
    "text": "The term \"spouse\" as used in this paragraph shall include any natural person qualifying as a domestic partner under the provisions of any applicable federal, state or local law in the United States of America,"
  },
  {
    "id": "c020",
    "name": "II.B. Estates and Legal Representatives — Coverage",
    "text": "B. Estates and Legal Representatives Coverage under this Policy shall extend to a Claim made against the estates, heirs, legal representatives or assigns of an Insured Individual who is deceased Of against the legal representatives or assigns of an Insured Individual who is incompetent, insolvent or bankrupt for the Wrongful Acts of such Insured Individual."
  },
  {
    "id": "c021",
    "name": "II.B. Estates and Legal Representatives — Exclusion",
    "text": "The coverage extension afforded by this Subsection does not apply to any Claim alleging any wrongful act or omission by the Insured individual's estates, heirs, legal representatives or assigns."
  },
  {
    "id": "c022",
    "name": "II.C. Extended Repoiting Period — Purchase Right",
    "text": "C. Extended Repoiting Period if the insurer chooses not to renew or the Parent Company cancels this Policy, the Policyholder or the Insured Individuals shall have the right, upon payment of the additional premium required by the Insurer in Item 5(A) in the Declarations, to a one year Extended Reporting Period following the termination of the Policy Period, but only with respect to Wrongful Acts occurring prior to the effective date of such cancellation or nonrenewal."
  },
  {
    "id": "c023",
    "name": "II.C. Extended Repoiting Period — Nonpayment Limitation",
    "text": "The right to purchase the Extended Reporting Period shall not be available in the event of nonrenewal or cancellation of this Policy resulting from the failure to Pay any premium due."
  },
  {
    "id": "c024",
    "name": "II.C. Extended Repoiting Period — Renewal Terms",
    "text": "The offer of renewal terms, conditions or pramiums different from those in effect prior to renewal shail not constitute a refusal to renew,"
  },
  {
    "id": "c025",
    "name": "II.C. Extended Repoiting Period — Election Deadline",
    "text": "This right to elect any Extended Reporting Pericd shall lapse unless written notice of the election, together with payment of the additional premium due, is given by the insuredand is received by the Insurer within sixty (60) days following the effective date of cancellation, or nonrenewal as appropriate."
  },
  {
    "id": "c026",
    "name": "II.C. Extended Repoiting Period — Applicable Claims",
    "text": "Coverage under the Extended Reporting Period shall apply only to a Claim that is first made against the Insured during the Extended Reporting Period,"
  },
  {
    "id": "c027",
    "name": "II.C. Extended Repoiting Period — Deemed Claim Date",
    "text": "and any Claim mace during the Extended Reporting Period shall be deemed fo have been made during the immediately preceding Policy Period."
  },
  {
    "id": "c028",
    "name": "II.C. Extended Repoiting Period — Liability Limit",
    "text": "The Limit of Liability applicable to the Extended Reporting Period shall be part of, and not in addition to, the Limit of Liability for the immediately preceding Policy Period."
  },
  {
    "id": "c029",
    "name": "III.A. Application",
    "text": "Hi. DEFINITIONS A. Application means each and every signed application, any attachments to such applications, other materials submitted therewith or incorporated therein and any other such documents submitted in connection with the underwriting of this policy or the underwriting of any other empioyment practices lability policy issued by the Insurer, or any of its affiliates, of which this policy is a renewal, replacement or which succeed it in time, as well as any publicly available documents that are filed by the Policyholder prior to the inception date of this Policy with the Department of Labor or the Equal Employment Opportunity Commission {cr any similar federal, state, local, or foreign reguiatory agency)."
  },
  {
    "id": "c030",
    "name": "III. Benefits",
    "text": "Benefits means perquisites, fringe benefits, defaned compensation or payments (including insurance premiums) in connection with an employee benefit olan and any other payment to or for the benefit of an employee arising out of the employment relationship, Benefits shail not include Salary, wages, commissions or nan-deferred cash incentive compensation."
  },
  {
    "id": "c031",
    "name": "III. Breach of Employment Contract",
    "text": "Breach of Employment Contract means a breach of any oral, written or implied amployment contract."
  },
  {
    "id": "c032",
    "name": "Section III.D — Claim definition",
    "text": "Claim means: 1. the receipt by any Insured of: a. a written demand against any Insured for monetary or non-monetary relief: b. a civil proceeding against any insured commenced by the service of a complaint or similar pleading; c. 4 formai, administrative, investigative or regulatory proceeding by or before the Equai Employment Opportunity Commission (EEOC), the Office of Federal Contract Compliance Programs (OFCCP), or a similar formal proceeding before another federal, state or other governmental agency against any Insured commenced by a notice of charges, forrnal investigative order or similar document: or d. an arbitration or other aiternative dispute resolution proceeding against any Insured commenced by a written demand or notice: 2. a written request received by an Insured to tall or waive 4 Statute of limitations relating to a matter described in subparagraph 1. above."
  },
  {
    "id": "c033",
    "name": "III.E. Defense Costs",
    "text": "E. Defense Costs means reasonable and necessary legal fees and expenses (other than reguiar or overtime wages, salaries, fees, benefits, or other campensation of the Insured individuals or Employees or the Policyholder's overhead €xpenses) incurred by or on behalf of the Insureds in defending, settling, appealing or investigating Claims, and the premiums for appeal, attachment or similar bonds. The Insurer, however, shall have no obligation to apply for or furnish such bonds."
  },
  {
    "id": "c034",
    "name": "III.F. Discrimination",
    "text": "F. Discrimination means the violation of any Federal, State, or local statute, regulation, ordinance or common law concerning discrimination in employment anywhere in the worid."
  },
  {
    "id": "c035",
    "name": "III.G. Employee",
    "text": "G. Employee means any one or more natural persons who are past, present or future: 1. duly appointed officer of the Policyholder. 2. individuals whose labor or service is directed by the Policyholder, whether such labor or service is on a part-time, temporary, seasonal, or full-time basis: 3. leased employees and volunteers whose labor or service is directed solely by the Policyholder: 4, applicants for prospective employment by the Policyholder. or 5. any individual contracted to perform work for the Policyholder or who is an independent contractor for the Policyholder, but only if such individual performs work or services solely for or on behalf of the Policyholder."
  },
  {
    "id": "c036",
    "name": "III.H. Harassment",
    "text": "H. Harassment means: 1. wark related sexual harassment that interferes with an Employee's performance or creates an intimidating hostile or offensive working environment: 2. sexual advances, requests for sexual favors, or other conduct of a sexual nature that is made a condition of employment or that is used as a basis for employment decisions; or — 3. ilegal work related harassment."
  },
  {
    "id": "c037",
    "name": "III.I. Insured",
    "text": "i insured means the Insured Individuals and the Policyholder."
  },
  {
    "id": "c038",
    "name": "III.J. Insured Individual",
    "text": "J. Insured Individual means any one or more natural persons who are past, present or future: 1. duly elected or appointed director, officer or trustee of the Policyholder or their functional equivalent if serving in such.a position outside the United States: 2. individuals compensated by the Policyhoider through wages, salary and/or commissions and whose labor or service is directed by the Policyholder, whether such labor of service is on a part-time, temporary, seasonal, or full-time basis: 3. volunteers whose labor or service is directed by the Policyholder: 4. individuals leased to the Policyholder, but only if prior to any Claim against such individual the Policyholder has agreed in writing to indemnify such individual or the company leasing that individual for matters within the scope of coverage of this Policy; or 5. individuals contracted to perform work for the Policyholder or who is an independent contractor for the Policyholder, but only if prior to any Claim against such individual the Policyholder has agreed in writing to indemnify such individual for matters within the scope of coverage of this Policy."
  },
  {
    "id": "c039",
    "name": "III.K. interrelated Wrongful Acts",
    "text": "K. interrelated Wrongful Acts means any or all Wrongful Acts that have as a cornmon nexus any fact, citcumstance, situation, event, transaction, cause or series of CauSaily or fogically connected facts, circumstances, situations, events, transactions or causes."
  },
  {
    "id": "c040",
    "name": "III.L. Loss",
    "text": "L. Loss means the amount which the Insureds become legally obligated to pay on account of a Claim, including damages (including front pay and back pay), judgments, any award of pre-judgment or postjudgment interest, settlement amounts, and costs and fees awarded pursuant to judgments, and Defense Costs. Loss does not include: 1. any amounts for which the Insureds are legally or financially absolved from payment; or 2. taxes or the loss of tax benefits, or fines or penalties imposed by law: or 3. the muitiple portion of any multiplied damage award: 4. the future salary, wages, commissions, or Benefits of a claimant who has been or shall be hired, promoted, or reinstated to employment pursuant to a settlement of. order in, or other resolution of any Claim; 5. any payment, incentive, or other compensation that is granted in the form of securities of the Policyholder or is based on the value of securities of the Policyholder: 6. any Salary, wages, commissions, Benefits or other monetary payments which constitute severance payments or payments pursuant to a notice period: 7. any amount incurred by an Insured in the defense or investigation of any action, proceeding, or demand that is not then a Claim even if (i) such amount also benefits the defense of a covered Claim. or (ii) such action, proceeding or demand subsequently gives rise toa Claim: . 8 matters uninsurable under the law applicable to this Policy: or 3. Punitive Damages. However, if Punitive Damage Coverage is included in Item 6 in the Declarations, Loss shall include Punitive Damages to the extent such damages are insurable. In determining the insurability of Punitive Damages, it is agreed that the law of the jurisdiction most favorable to the insurability of those damages will control for the purpose of resolving any dispute between the Insurer and the insureds, provided that such jurisdiction is: {a) where the Punitive Damages were awarded or imposed: (b) where the Wrongful Act underlying the Claim took piace: ic) where either the insurer or any Insured is incorporated, has its principal place of business or resides; or (dj) where this Policy was issued or became effective."
  },
  {
    "id": "c041",
    "name": "III.M. Other Workplace Tort",
    "text": "M. Other Workplace Tort means 1. an employment related misrepresentation to an employee: 2. failure to grant or adopt adequate employment related policies and procedures: 3. negligent hiring, supervision, evaluation or retention of employees; 4. employment-related invasion of privacy or defamation, 3. employment-related wrongful infliction of emotional distress: or EP 0001 (Ed. 1005) Page 4 of 13 Printed in U.S.A. 5. employment-related ibel, slander, false arrest, detention imprisonment: but only when alleged as part of a Claim for an actual or alleged Breach of Employment Contract, Discrimination, Harassment, Retaliation, or Wrongful Job Action."
  },
  {
    "id": "c042",
    "name": "III.N. Parent Company",
    "text": "N. Parent Company means the company designated in Item 1 in the Declarations."
  },
  {
    "id": "c043",
    "name": "III.O. Policyholder",
    "text": "QO. Policyholder means the Parent Company and its Subsidiaries, including any such organization as a debtor in possession within the meaning of the United States Bankruptcy Code or similar legat status under foreign law."
  },
  {
    "id": "c044",
    "name": "III.P. Policy Period",
    "text": "P. Policy Period means the period of time specified in Item 2 in the Declarations, subject to prior termination in accordance with Section VILC."
  },
  {
    "id": "c045",
    "name": "III.Q. Pollutants",
    "text": "Q. Pollutants means any substance located anywhere in the worid exhibiting any hazardous characteristics as defined by or identified on a list of hazardous substances issued by the United States Environmental Protection Agency or any federal, state, county, municipality or locality counterpart thereof. Such substances shall include, without limitation, solids, liquids, gaseous or thermal irritants, contaminants or smoke, vapor, soot, fumes, acids, alkalis, mold, spores, fungi, germs, chemicals or waste materials. Pollutants shall also mean any other air emission, odor, waste water, oil or oil product, infectious or medical waste, asbestos or asbestos product, lead or lead product, noise, and electric, magnetic or electromagnetic field."
  },
  {
    "id": "c046",
    "name": "III.R. Potential Claim",
    "text": "R. Potential Claim means an allegation or accusation, by or on behalf of a potential claimant, of a Wrongful Employment Act provided such allegation does not constitute a Claim, but subsequently may give rise to a Claim."
  },
  {
    "id": "c047",
    "name": "III.S. Punitive Damages",
    "text": "S. Punitive Damages means punitive or exemplary damages and also includes liquidated damages awarded under the Age Discrimination in Employment Act (ADEA), Equal Pay Act (EPA), and Family and Medical Leave Act (FMLA), all as amended."
  },
  {
    "id": "c048",
    "name": "III.T. Retaliation",
    "text": "T. Retaliation means the illegal retaliatory treatment of Employees, including any retaliatory treatment against an Employee for such Employee engaging in any of the following activities: 1. exercising his or her rights under the law. 2. refusing to violate any law or opposing an unlawful practice: 3. threatening to disclose or actually disclosing violations of the law to any governmental authority or the management of the Policyholder, or 4. testifying, cooperating, or assisting with respect to an investigation or proceeding by a governmental authonty against the Policyholder."
  },
  {
    "id": "c049",
    "name": "III.U. Subsidiary",
    "text": "U. Subsidiary means any entity in which and sa long as the Parent Company, either directly or indirectly. 1. owns more than fifty (50) percent of the issued and outstanding voting equity securities, or 2. controls voting rights representing the present right to vote for election or to appoint more than fitty (50) percent of the directors or trustees, on or betore the effective date of this Policy, or after the effective date of this Policy if the entity is. covered pursuant {o Section VIILA.1, solely with regard to Wrongful Acts occurring at or after. the time such entity becarne a Subsidiary."
  },
  {
    "id": "c050",
    "name": "III.V. Third Party Claim",
    "text": "V. Third Party Claim means any Claim brought and maintained against any Insured by or on behalf of any natural person who is, or attempted to be, a customer or vendor of the Policyholder or an EP 0001 (Ed. 1005) Page 5 of 13 Printed in U.S.A. employee of such customer or vendor of the Policyholder for any Wrongful Third Party Act. Third Party Claims shail not include Claims brought by independent contractors of the Policyholder."
  },
  {
    "id": "c051",
    "name": "III.W. Wrongful Act",
    "text": "W. Wrongful Act means a Wrongful Employment Act or a Wrongful Third Party Act."
  },
  {
    "id": "c052",
    "name": "III.X. Wrongful Employment Act",
    "text": "X. Wrongful Employment Act means any Breach of Employment Contract, Discrimination, Harassment, Retaliation, Wrongful Job Action, or Other Workplace Torts actually or allegedly committed or attempted by: 1. the Policyholder, 2. any Insured Individuals in their capacities as such: or 3. by any other persons for whom the Insureds are legally responsible."
  },
  {
    "id": "c053",
    "name": "III.Y. Wrongful Job Action",
    "text": "Y. Wrongful Job Action means wrongful: 1. dismissal, discharge or termination (either actual or constructive) of employment: 2. wrongful failure to ernploy or promote: 3. wrongful reference, discipline or deprivation of a career opportunity; or 4. wrongful demotion or adverse change in the terms, conditions or status of employment."
  },
  {
    "id": "c054",
    "name": "III.Z. Wrongful Third Party Act",
    "text": "2. Wrongful Third Party Act means any error, misstatement, misleading statement, act, omission, neglect, or breach of duty actually or allegedly committed or attempted by: 7. the Policyholder; 2. any Insured Individuals in their capacities as such: or 3. by any other persons for whom the Insureds are legally responsible; and which discriminates against any natural person who is a customer or vendor of the Policyholder, or employee of a customer or vendor of the Policyholder, on the basis of that natural person's race, color, creed, national origin, gender, sexual orientation or preference, marital siatus, sex, religion, age, military service, disability or handicap, pregnancy, or on any other basis prohibited by law, including the sexual or other discriminatory harassment of such customer or vendor or employee of such customer or vendor."
  },
  {
    "id": "c055",
    "name": "IV.A. Exclusions Applicable to All Loss",
    "text": "IV. EXCLUSIONS A. Exclusions Applicable to All Loss The Insurer shall not be liable for Loss arising from any Claim made against any Insured: 1. based upon, arising out of, directly or indirectly resulting from, in consequence of or in any way involving any fact, circumstance. transaction, event or Wrongful Act which before the Inception Date set forth in item 2 of the Declarations, was the subject of any notice of claim, loss or notice of potential claim or potential loss given under any other policy of insurance: 2. based upon, arising out of. directly or indirectly resulting from, in consequence of or in any way invalving: (a) any demand, suit, or other proceeding pending, or order, decree or judgment entered, against any Insured on or prior to the Pending or Prior Claim Date set forth in Item 9 in the Declarations or any Wrongful Act, fact, circumstance or situation underlying or alleged therein; or EP 0001 (Ed. 1005) Page 6 of 13 Printed in U.S.A, (b) any other Wrongful Act whenever occurring, which, together with a Wrongful Act described in (a) above, constitute Interrelated Wrongful Acts: 3. based upon, arising out of, directly or indirectly resulting from, in consequence of or in any way involving any action that relates to a collective bargaining agreement: 4. based upon, arising from, or in consequence of the liability of others assumed by any Insured under any written or oral contract or agreement; pravided that this Exclusion A. 4 shall not appty to the extent that an Insured would have been liable in the absence of such a contract or agreement: 5. for an actual or alleged violation of the responsibilities, obligations or duties imposed by the following laws and any amendments thereto: (a) any law governing workers’ compensation, unemployment insurance, social security, disability benefits or similar law; (b) the Employee Retirement Income Security Act of 1974 (except Section 510 thereof) or any law that governs any employee benefit arrangement, program, policy, plan or scheme of any type (whether or not legally required or whether provided during or subsequent to employment with the Policyholder): (c) the Fair Labor Standards Act or any law that governs wage, hour or payroll policies and practices, except the Equal Pay Act; (d) the National Laber Relations Act or any law that pertains to the rights of employees with raspect to unions, unionizing, or collective activities in the workplace or any obligations of employers with respect to such employee activities: (@) the Worker Adjustment and Retraining Notification Act, or any law that governs any obligation of an employer to notify, discuss, or bargain with its employees or others in advance of any plant or facility closing, or mass layoff or any similar obligation; (f} the Consolidated Omnibus Budget Reconciliation Act of 1985; (g) the Federal False Claims Act or any similar federal, state, or local statutory law or common law anywhere in the world; or | (h} the Occupational Safety and Heaith Act or any law that governs workplace safety and heaith: including any other federal, state local or foreign statute or law similar to any statute or law descnbed in (a) through (h) of this exclusion, or rules or regulations promulgated under any of © such statutes or laws, provided however this Exclusion A. 5. shall not apply to any Claim for Retaliation; 8. made against a Subsidiary or an insured Indvidual of such Subsidiary for any Wrongful Act committed, attempted, or allegedly committed or attempted during anytime when such entity was not a Subsidiary: 7. based upon, arising out of, directly or indirectly resulting from, in consequence of or in any way involving: (a) any nuclear reaction, radiation or contamination; (b) the actual, alleged or threatened discharga, release, escape, seepage, migration, dispersal or disposal of Pollutants into or on real or personal property, water or the atmosphere: or EP 0001 (Ed. 1005) Page 7 of 13 Printed in U.S.A. {c) any direction or request that the Insureds test for, monitor, clean up, remove, contain, treat, detoxify or neutralize Pollutants, or any voluntary decision to do 80; provided that this Exclusion A. 7. shall not apply to Claims brought by an Employee for Retaliation, 8. for actual or alleged bodily injury, mental anguish, emctionai distress, humiliation, assault, battery, sickness, disease, or death of any person or damage to or destruction of any tangible property including loss of use thereof, provided that this exclusion shail not apply with respect to any actual or alleged mental anguish or emotional distress in a Claim or Third Party Claim for a Wrongful Act by an Insured: 9. for any actual or alleged breach of any express contract between the Policyhoider and an independent contractor of the Poticyholder, 10. for any actual or alleged charge of contempt of court or violation of a court order. 11. based upon, arising from, or in consequence of any federal, state, or jocal statutory law or common law anywhere in the world that governs competition, monopolistic practices, or price fixing (including horizontal or other price fixing of wages, hours, salaries, compensation, benefits or any other terms and conditions of employment), including but not limited to the Interstate Commerce Act of 1887, the Sherman Antitrust Act of 1890, the Clayton Act of 1914, the Robinson-Patman Act of 1936, the Cellar-Kefauver Act of 1950, the Federal Trade Commission Act of 1914, or amendments to or regulations promuigated under any such law: or 12. based upon, arising out of, directly or indirectly resulting from, in consequence of or in any way involving: (a) the gaining of any profit, remuneration, or advantage to which the Insured was not legaliy entitled: ar (b) any criminal or deliberately fraudulent act, error or omission by an insured, if evidenced by any judgment, final adjudication, alternate dispute resolution proceeding or a document or written statement by an Insured."
  },
  {
    "id": "c056",
    "name": "IV.A.12(b). Non-Imputation of Knowledge",
    "text": "With respect ta exclusion A. 12 (b) set forth above no knowledge possessed by any Insured Individual shall be imputed to any other Insured Individual."
  },
  {
    "id": "c057",
    "name": "IV.B. Exclusions Applicable Solely to Loss Other Than Defense Costs",
